func:
// THE NAME-MATCHING TABLE (also called a "crosswalk" or "asset register").
// Each row says: these different names, in three different systems,
// all mean the SAME room. We use the sensor names (room1..room6) as the
// one official ID, and translate everything else into it.
const rooms = [
  { id: "room1", name: "Reception",      sensor: "room1", bms: "AHU-L1-RCP", cafm_location: "FLR1-001", cafm_name: "Front Desk Area",  cafm_ahu_asset: "AST-1001" },
  { id: "room2", name: "Open Office",    sensor: "room2", bms: "AHU-L1-OPN", cafm_location: "FLR1-002", cafm_name: "Open Plan Office", cafm_ahu_asset: "AST-1002" },
  { id: "room3", name: "Meeting Room",   sensor: "room3", bms: "AHU-L1-MTG", cafm_location: "FLR1-003", cafm_name: "Meeting Rm 01",    cafm_ahu_asset: "AST-1003" },
  { id: "room4", name: "Kitchen",        sensor: "room4", bms: "AHU-L1-KIT", cafm_location: "FLR1-004", cafm_name: "Staff Kitchen",    cafm_ahu_asset: "AST-1004" },
  { id: "room5", name: "Manager Office", sensor: "room5", bms: "AHU-L1-MGR", cafm_location: "FLR1-005", cafm_name: "Mgr Office",       cafm_ahu_asset: "AST-1005" },
  { id: "room6", name: "Quiet Room",     sensor: "room6", bms: "AHU-L1-QUI", cafm_location: "FLR1-006", cafm_name: "Focus Pod",        cafm_ahu_asset: "AST-1006" }
];

// Quick look-up lists, like the index at the back of a book:
// "AHU-L1-MTG? -> room3", "FLR1-003? -> room3", and so on.
const map = { rooms: {}, bySensor: {}, byBms: {}, byLocation: {} };
const twin = {};
for (const r of rooms) {
  map.rooms[r.id] = r;
  map.bySensor[r.sensor] = r.id;
  map.byBms[r.bms] = r.id;
  map.byLocation[r.cafm_location] = r.id;

  // An empty "folder" for each room, filled in by the lanes below
  twin[r.id] = {
    id: r.id,
    name: r.name,
    ids: { sensor: r.sensor, bms: r.bms, cafm_location: r.cafm_location,
           cafm_name: r.cafm_name, cafm_ahu_asset: r.cafm_ahu_asset },
    summary: {},
    sensors: {},
    ahu: { id: r.bms },
    assets: [],
    tickets: { open: [], history: [] },
    alert: { level: "unknown", message: "Waiting for data", reasons: [] }
  };
}

flow.set("map", map);
flow.set("twin", twin);
flow.set("lastSeen", { sensors: null, bms: null, cafm: null, cafm_error: null });
node.status({ fill: "green", shape: "dot", text: rooms.length + " rooms mapped" });
return null;

// A room sensor reading arrived, e.g. {"room":"room3","sensor":"temperature","value":24.1,...}
const map = flow.get("map");
const twin = flow.get("twin");
const p = msg.payload;
if (!map || !twin || !p || typeof p !== "object") return null;

const sensorName = p.room || msg.topic.split("/")[2];
const roomId = map.bySensor[sensorName];
if (!roomId) {
  node.warn("No match in the name table for sensor room: " + sensorName);
  return null;
}

twin[roomId].sensors[p.sensor] = { value: p.value, unit: p.unit, time: p.time };
twin[roomId].sensors_received = Date.now();
flow.get("lastSeen").sensors = Date.now();
node.status({ fill: "green", shape: "dot", text: sensorName + " -> " + roomId });
return null;

// An air machine (AHU) reading arrived from the BMS gateway,
// e.g. topic bms/AHU-L1-MTG/Status, payload {"device":"AHU-L1-MTG","point":"Status","value":"Fault",...}
const map = flow.get("map");
const twin = flow.get("twin");
const p = msg.payload;
if (!map || !twin || !p || typeof p !== "object") return null;

const roomId = map.byBms[p.device];
if (!roomId) {
  node.warn("No match in the name table for BMS device: " + p.device);
  return null;
}

// Friendlier names for the five BMS points
const POINTS = { Status: "status", SupplyTemp: "supply_temp", Setpoint: "setpoint",
                 FanSpeed: "fan_speed", Alarm: "alarm" };
const ahu = twin[roomId].ahu;
ahu[POINTS[p.point] || p.point] = p.value;
ahu.received = Date.now();
flow.get("lastSeen").bms = Date.now();
node.status({ fill: "green", shape: "dot", text: p.device + " -> " + roomId });
return null;

// Keep the asset list safe, then ask the CAFM for the tickets.
// We start a brand-new message on purpose: the old one carries the
// CAFM's reply headers, which would confuse the next request.
return { assets: msg.payload, assetsStatus: msg.statusCode };

// We now have both CAFM lists: msg.assets (equipment) and msg.payload (tickets).
// The CAFM never says "room3". It says "FLR1-003" and "AST-1003".
// So we join in two steps:  ticket -> asset -> location code -> our room.
const map = flow.get("map");
const twin = flow.get("twin");
const lastSeen = flow.get("lastSeen");
if (!map || !twin) return null;

const assets = msg.assets;
const tickets = msg.payload;
if (!Array.isArray(assets) || !Array.isArray(tickets)) {
  lastSeen.cafm_error = "CAFM not reachable on localhost:8000";
  node.status({ fill: "red", shape: "ring", text: "CAFM not reachable" });
  return null;
}

// Step 1: which room is each asset in?
const roomOfAsset = {};
const assetById = {};
const unmatched = [];
const newAssets = {};
for (const id in twin) newAssets[id] = [];
for (const a of assets) {
  const roomId = map.byLocation[a.location_code];
  if (!roomId) { unmatched.push(a.asset_id); continue; }
  roomOfAsset[a.asset_id] = roomId;
  assetById[a.asset_id] = a;
  newAssets[roomId].push({
    asset_id: a.asset_id, description: a.description, category: a.category,
    model: a.model, installed: a.installed, last_service: a.last_service,
    next_service: a.next_service, condition: a.condition,
    serves_room_air: a.asset_id === map.rooms[roomId].cafm_ahu_asset
  });
}

// Step 2: which room is each ticket for (via its asset)?
const newTickets = {};
for (const id in twin) newTickets[id] = { open: [], history: [] };
for (const t of tickets) {
  const roomId = roomOfAsset[t.asset_id];
  if (!roomId) continue;
  const item = {
    ticket_id: t.ticket_id, asset_id: t.asset_id,
    asset: assetById[t.asset_id].description, type: t.type, priority: t.priority,
    title: t.title, status: t.status, reported_by: t.reported_by,
    assigned_to: t.assigned_to, opened: t.opened, closed: t.closed,
    resolution: t.resolution
  };
  if (String(t.status).toLowerCase() === "open") newTickets[roomId].open.push(item);
  else newTickets[roomId].history.push(item);
}

// Step 3: file everything into each room's folder (newest first)
for (const id in twin) {
  newTickets[id].history.sort((a, b) => String(b.opened).localeCompare(String(a.opened)));
  twin[id].assets = newAssets[id];
  twin[id].tickets = newTickets[id];
}

lastSeen.cafm = Date.now();
lastSeen.cafm_error = null;
const openCount = tickets.filter(t => String(t.status).toLowerCase() === "open").length;
let text = assets.length + " assets, " + openCount + " open tickets matched";
if (unmatched.length) text += " (" + unmatched.length + " unmatched)";
node.status({ fill: unmatched.length ? "yellow" : "green", shape: "dot", text: text });
return null;

// Every 5 seconds: tidy each room into one simple summary, check the
// alert rule, then publish  twin/room1 ... twin/room6  on MQTT.
const twin = flow.get("twin");
const lastSeen = flow.get("lastSeen");
if (!twin) return null;

// ---- Settings you can change ----
const HOT = 25;          // °C: above this a room counts as "hot"
const CO2_HIGH = 1000;   // ppm: above this the air is "stuffy"
const STALE_MS = 30000;  // no news for 30 s = that source has gone quiet
// ---------------------------------

const now = Date.now();
function health(ts, maxAge) {
  if (!ts) return "waiting";
  return now - ts < maxAge ? "ok" : "stale";
}
flow.set("health", {
  sensors: health(lastSeen.sensors, STALE_MS),
  bms: health(lastSeen.bms, STALE_MS),
  cafm: lastSeen.cafm_error ? "offline" : health(lastSeen.cafm, 60000)
});

const previous = context.get("previous") || {};
const roomMsgs = [];
const alertMsgs = [];
let alarms = 0, warnings = 0;

for (const r of Object.values(twin)) {
  const s = r.sensors;
  const temp = s.temperature ? s.temperature.value : null;
  const co2 = s.co2 ? s.co2.value : null;
  const people = s.occupancy ? s.occupancy.value : null;
  const ahuStatus = r.ahu.status || null;
  const fresh = r.sensors_received && now - r.sensors_received < STALE_MS;

  r.summary = {
    temperature: temp, co2: co2, occupancy: people,
    ahu_status: ahuStatus, ahu_setpoint: r.ahu.setpoint ?? null,
    ahu_fan_speed: r.ahu.fan_speed ?? null, ahu_alarm: r.ahu.alarm || null,
    open_tickets: r.tickets.open.length, data_fresh: !!fresh
  };

  // ---- THE ALERT RULE: combine all three sources ----
  const hot = temp !== null && temp > HOT;
  const fault = ahuStatus === "Fault";
  const stuffy = co2 !== null && co2 > CO2_HIGH;
  // Tickets for this room's air machine: "Reactive" = someone reported a problem,
  // "Planned" = scheduled work (e.g. an overdue service that may explain the fault)
  const ahuOpen = r.tickets.open.filter(t => t.asset_id === r.ids.cafm_ahu_asset);
  const ahuTickets = ahuOpen.filter(t => t.type === "Reactive");
  const plannedTickets = ahuOpen.filter(t => t.type !== "Reactive");
  const ticketText = ahuTickets.map(t => "#" + t.ticket_id + " " + t.title).join("; ");
  const plannedText = plannedTickets.map(t => "#" + t.ticket_id + " " + t.title).join("; ");

  const reasons = [];
  if (hot) reasons.push("Temperature " + temp + " °C is above " + HOT + " °C");
  if (fault) reasons.push("Air machine " + r.ids.bms + " is in Fault: " + (r.ahu.alarm || "no alarm text"));
  if (stuffy) reasons.push("CO2 " + co2 + " ppm is above " + CO2_HIGH + " ppm");
  if (ahuTickets.length) reasons.push("Problem already reported: " + ticketText);
  if (plannedText && (hot || fault)) reasons.push("Planned work still open on this air machine: " + plannedText);

  let level, message;
  if (temp === null) {
    level = "unknown"; message = "No sensor data yet";
  } else if (hot && fault) {
    level = "alarm";
    message = r.name + " is overheating because its air machine " + r.ids.bms + " has failed (" +
      (r.ahu.alarm || "fault") + "). " +
      (ahuTickets.length ? "Already logged as ticket " + ticketText + "."
                         : "No repair ticket is open yet: one should be raised.");
  } else if (fault) {
    level = "warning";
    message = "Air machine " + r.ids.bms + " has failed (" + (r.ahu.alarm || "fault") +
      ") but " + r.name + " is not hot yet.";
  } else if (hot) {
    level = "warning"; message = r.name + " is warm, but its air machine looks OK.";
  } else if (stuffy) {
    level = "warning"; message = r.name + " air is stuffy (CO2 " + co2 + " ppm).";
  } else {
    level = "ok"; message = "All normal.";
  }
  r.alert = { level: level, message: message, reasons: reasons, ticket_logged: ahuTickets.length > 0 };
  r.updated = new Date(now).toISOString();
  if (level === "alarm") alarms++;
  if (level === "warning") warnings++;

  roomMsgs.push({ topic: "twin/" + r.id, payload: r, retain: true });

  // Only announce an alert when it CHANGES, so we don't shout every 5 seconds
  const key = level + "|" + r.alert.ticket_logged + "|" + (fault ? "F" : "") + (hot ? "H" : "") + (stuffy ? "S" : "");
  if (previous[r.id] !== key) {
    const firstLook = previous[r.id] === undefined;
    previous[r.id] = key;
    // (no need to announce "all normal" the very first time we see a room)
    if (level !== "unknown" && !(firstLook && level === "ok")) {
      alertMsgs.push({ topic: "twin/alerts", retain: false,
        payload: { room: r.id, name: r.name, level: level, message: message,
                   reasons: reasons, time: r.updated } });
    }
  }
}
context.set("previous", previous);

node.status({
  fill: alarms ? "red" : warnings ? "yellow" : "green", shape: "dot",
  text: alarms + " alarm, " + warnings + " warning"
});
return [roomMsgs, alertMsgs];

// Someone visited http://localhost:1880/twin : hand over the whole building.
const twin = flow.get("twin") || {};
msg.payload = {
  building: "Mini Twin office",
  generated: new Date().toISOString(),
  sources: flow.get("health") || {},
  rooms: Object.values(twin)
};
msg.headers = { "Access-Control-Allow-Origin": "*" };
return msg;

// Someone visited http://localhost:1880/twin/<name>.
// They can use ANY of the room's names: room3, Meeting Room,
// AHU-L1-MTG, FLR1-003, Meeting Rm 01 or AST-1003. The table does the matching.
const twin = flow.get("twin") || {};
const map = flow.get("map") || { rooms: {} };
const asked = decodeURIComponent(msg.req.params.room || "").trim().toLowerCase();

let found = null;
for (const r of Object.values(map.rooms)) {
  const names = [r.id, r.name, r.bms, r.cafm_location, r.cafm_name, r.cafm_ahu_asset];
  if (names.some(n => String(n).toLowerCase() === asked)) { found = r.id; break; }
}
msg.headers = { "Access-Control-Allow-Origin": "*" };
if (!found) {
  msg.statusCode = 404;
  msg.payload = { error: "No room called '" + asked + "'", try: Object.keys(map.rooms) };
} else {
  msg.payload = { asked: asked, matched: found, sources: flow.get("health") || {}, room: twin[found] };
}
return msg;
